1	//! The commit that set a package's version, so a rerun after a half-finished release cannot tag later code.
2	
3	use std::cell::RefCell;
4	use std::collections::{BTreeMap, BTreeSet};
5	use std::path::PathBuf;
6	use std::sync::{Mutex, MutexGuard, PoisonError};
7	
8	use callisto_manifests::{read_effective_version, WorkspaceReads};
9	use callisto_model::vcs::GitAccess;
10	use callisto_model::{ManifestDecl, ManifestError, ReleaseDecisionV1, ReleasePackageId, Version};
11	
12	use crate::changed::package_paths;
13	use crate::commands::git_batch::{batch_blobs, BatchBlob};
14	use crate::{DependencyResolver, GraphError, Workspace};
15	
16	/// A package whose files differ from the commit that set the version it is about to release, or whose version
17	/// commit could not be found.
18	pub(super) struct MovedPast {
19	    pub package: ReleasePackageId,
20	    pub version: String,
21	    /// `None` when no commit on the first-parent history sets this version.
22	    pub version_commit: Option<String>,
23	}
24	
25	/// The selected packages that differ from the commit that set their release version, or whose version commit is
26	/// unknown. `resumable` packages are tagged on HEAD already.
27	///
28	/// A package is compared by tree content, so a revert or a change made only inside a merge commit counts the same as
29	/// a plain commit. The caller refuses only the ones whose version the registry already holds.
30	pub(super) fn packages_moved_past_their_version<R: callisto_model::CommandRunner, D: DependencyResolver>(
31	    workspace: &Workspace<'_, R, D>,
32	    decision: &ReleaseDecisionV1,
33	    resumable: &BTreeSet<ReleasePackageId>,
34	) -> Result<Vec<MovedPast>, GraphError> {
35	    let git = workspace.git_access();
36	    let mut candidates = Vec::new();
37	    for package in workspace.graph.packages() {
38	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
39	        let Some(entry) = decision
40	            .entries
41	            .iter()
42	            .find(|entry| ids.contains(&entry.package) && !resumable.contains(&entry.package))
43	        else {
44	            continue;
45	        };
46	        // A package with no manifest has no version to have been set.
47	        if let Some(manifest) = package.canonical_manifests().next() {
48	            candidates.push((package, entry, manifest));
49	        }
50	    }
51	
52	    // Every manifest at `HEAD` in one read; each package's own history is then read side by side.
53	    let reads = RevReads::new(git);
54	    let at_head: Vec<(String, PathBuf)> = candidates
55	        .iter()
56	        .map(|(_, _, manifest)| ("HEAD".to_owned(), manifest.path.clone()))
57	        .collect();
58	    reads.preload(&at_head)?;
59	    let version_commits = super::capability::in_parallel(&candidates, |(_, entry, manifest)| {
60	        // A manifest that is not committed has no history to compare; the clean-tree rule covers it.
61	        let Some(head) = effective_version_at(&reads, "HEAD", manifest)? else {
62	            return Ok(None);
63	        };
64	        commit_setting_version(&reads, git, manifest, &head, &entry.target_version).map(Some)
65	    });
66	    let mut checked = Vec::new();
67	    for ((package, entry, _), version_commit) in candidates.into_iter().zip(version_commits) {
68	        if let Some(version_commit) = version_commit? {
69	            checked.push((package, entry, version_commit));
70	        }
71	    }
72	
73	    // A package is compared by tree content: each of its directories at the version commit and at `HEAD`, by object id,
74	    // all asked for in one read.
75	    let mut objects = Vec::new();
76	    for (package, _, version_commit) in &checked {
77	        let Some(commit) = version_commit else {
78	            continue;
79	        };
80	        for directory in package_paths(package) {
81	            let directory = if directory.as_path() == std::path::Path::new(".") {
82	                String::new()
83	            } else {
84	                directory.to_string_lossy().into_owned()
85	            };
86	            objects.push(format!("{commit}:./{directory}"));
87	            objects.push(format!("HEAD:./{directory}"));
88	        }
89	    }
90	    let mut ids = git.object_ids(&objects)?.into_iter();
91	    let mut moved = Vec::new();
92	    for (package, entry, version_commit) in checked {
93	        let unchanged = version_commit.is_some()
94	            && package_paths(package)
95	                .iter()
96	                .all(|_| ids.next().flatten() == ids.next().flatten());
97	        if !unchanged {
98	            moved.push(MovedPast {
99	                package: entry.package.clone(),
100	                version: entry.target_version.render().to_owned(),
101	                version_commit,
102	            });
103	        }
104	    }
105	    Ok(moved)
106	}
107	
108	/// The newest first-parent commit whose manifest holds `version` while its parent's does not.
109	///
110	/// Only the manifest and, for an inherited version, the workspace manifest that declares it can set the version, so
111	/// those are the only paths walked. A history with no such commit gives `None`, never a guess.
112	fn commit_setting_version(
113	    reads: &RevReads<'_, '_>,
114	    git: &GitAccess<'_>,
115	    manifest: &ManifestDecl,
116	    head: &callisto_manifests::EffectiveManifestVersion,
117	    version: &Version,
118	) -> Result<Option<String>, GraphError> {
119	    let mut paths = vec![manifest.path.clone()];
120	    if head.authority != manifest.path {
121	        paths.push(head.authority.clone());
122	    }
123	    for commit in git.first_parent_commits_touching(&paths)? {
124	        // A root commit has no parent, so the version was set there.
125	        let parent = format!("{commit}^");
126	        let wanted: Vec<(String, PathBuf)> = [&commit, &parent]
127	            .into_iter()
128	            .flat_map(|rev| paths.iter().map(move |path| (rev.clone(), path.clone())))
129	            .collect();
130	        reads.preload(&wanted)?;
131	        if effective_version_at(reads, &commit, manifest)?
132	            .map(|found| found.version)
133	            .as_ref()
134	            != Some(version)
135	        {
136	            continue;
137	        }
138	        let before = effective_version_at(reads, &parent, manifest)?;
139	        if before.map(|found| found.version).as_ref() != Some(version) {
140	            return Ok(Some(commit));
141	        }
142	    }
143	    Ok(None)
144	}
145	
146	/// Manifest text by revision and path, fetched in batches and kept: the same file is wanted by many packages (an
147	/// inherited version's workspace manifest) and at both a commit and its parent.
148	struct RevReads<'g, 'r> {
149	    git: &'g GitAccess<'r>,
150	    cache: Mutex<BTreeMap<(String, PathBuf), Option<String>>>,
151	}
152	
153	impl<'g, 'r> RevReads<'g, 'r> {
154	    fn new(git: &'g GitAccess<'r>) -> Self {
155	        RevReads {
156	            git,
157	            cache: Mutex::new(BTreeMap::new()),
158	        }
159	    }
160	
161	    fn entries(&self) -> MutexGuard<'_, BTreeMap<(String, PathBuf), Option<String>>> {
162	        self.cache.lock().unwrap_or_else(PoisonError::into_inner)
163	    }
164	
165	    /// Fetches every wanted `(revision, path)` not yet held with one `git cat-file --batch`.
166	    fn preload(&self, wanted: &[(String, PathBuf)]) -> Result<(), GraphError> {
167	        let missing: BTreeSet<&(String, PathBuf)> = {
168	            let held = self.entries();
169	            wanted.iter().filter(|key| !held.contains_key(*key)).collect()
170	        };
171	        if missing.is_empty() {
172	            return Ok(());
173	        }
174	        let objects: Vec<String> = missing
175	            .iter()
176	            .map(|(rev, path)| format!("{rev}:./{}", path.display()))
177	            .collect();
178	        let blobs = batch_blobs(self.git.runner(), self.git.root(), &objects)?;
179	        let mut held = self.entries();
180	        for ((rev, path), blob) in missing.into_iter().zip(blobs) {
181	            let text = match blob {
182	                BatchBlob::Blob(text) => Some(text),
183	                BatchBlob::Missing => None,
184	            };
185	            held.insert((rev.clone(), path.clone()), text);
186	        }
187	        Ok(())
188	    }
189	
190	    /// The text of `path` at `rev`, `None` when it has none there.
191	    fn text(&self, rev: &str, path: &std::path::Path) -> Result<Option<String>, GraphError> {
192	        let key = (rev.to_owned(), path.to_path_buf());
193	        if let Some(held) = self.entries().get(&key) {
194	            return Ok(held.clone());
195	        }
196	        self.preload(std::slice::from_ref(&key))?;
197	        Ok(self.entries().get(&key).cloned().flatten())
198	    }
199	}
200	
201	/// The version `manifest` holds at `rev`, resolving a workspace-inherited one. A manifest that is absent, does not
202	/// parse or declares no version there gives `None`; a failing git read is an error.
203	fn effective_version_at(
204	    reads: &RevReads<'_, '_>,
205	    rev: &str,
206	    manifest: &ManifestDecl,
207	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
208	    // `read_effective_version` reports manifest errors only, so a git failure is held here and returned after.
